window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d1ad7aab71ab591a"]={"versions": [{"id": "FIG-d1ad7aab71ab591a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Timing-Modells im Kontext des Virtual Functional Bus (AUTOSAR VFB). Das Diagramm definiert die konzeptionelle Metamodell-Struktur für Timing-Ketten (TimingChains), deren Zusammensetzung aus Teilstrecken sowie die Laufzeit-Repräsentation durch konkrete Aktivierungen und Ereignisvorkommen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert vier Klassen und deren strukturelle Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>Event</code> (abstrakt): Definiert das Ereigniskonzept. Assoziiert mit <code>EventOccurrence</code> über die Assoziationsenden <code>+event</code> (Multiplizität 1) und <code>+occurrences</code> (Multiplizität <code>*</code>).</li>\n<li><code>TimingChain</code>: Repräsentiert eine Timing-Kette. Enthält eine reflexive Komposition <code>+segments</code> mit Multiplizität <code>1..* {ordered}</code> zur hierarchischen/sequenziellen Unterteilung in Kettenglieder. Referenziert genau ein auslösendes Ereignis über die Assoziation <code>+stimulus</code> (Multiplizität 1) sowie genau ein resultierendes Ereignis über <code>+response</code> (Multiplizität 1) zur Klasse <code>Event</code>.</li>\n<li><code>TimingChainActivation</code>: Repräsentiert eine konkrete Ausführung/Aktivierung einer Timing-Kette. Steht in einer 1-zu-n-Beziehung (<code>1</code> zu <code>*</code>) zu <code>TimingChain</code>. Besitzt das Attribut <code>+ responseTime: TimeInterval</code>. Referenziert genau ein auslösendes Ereignisvorkommen über <code>+stimulus</code> (Multiplizität 1) und genau ein Ziel-Ereignisvorkommen über <code>+response</code> (Multiplizität 1) der Klasse <code>EventOccurrence</code>.</li>\n<li><code>EventOccurrence</code>: Repräsentiert das Eintreten eines konkreten Ereignisses mit dem Attribut <code>+ occurrenceTime: TimePoint</code>. Steht als Ausprägungsinstanz in n-zu-1-Beziehung zu <code>Event</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet die statische Korrelation von Entwurfselementen zu deren dynamischen Laufzeitinstanzen ab. Eine <code>TimingChain</code> wird dynamisch durch <code>TimingChainActivation</code> instanziiert, wobei die gemessene Reaktionszeit <code>responseTime</code> der Differenz zwischen dem auslösenden Stimulus-Ereigniszeitpunkt (<code>occurrenceTime</code> des Stimulus-<code>EventOccurrence</code>) und dem Antwort-Ereigniszeitpunkt (<code>occurrenceTime</code> des Response-<code>EventOccurrence</code>) entspricht. Die Segmentierung verlangt eine durchgängige kausale Kette über geordnete Zwischenschritte (<code>segments</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Modellierung und Werkzeugunterstützung gelten folgende OCL- bzw. Konsistenzbedingungen (<code>constraints</code>) auf <code>TimingChain</code>:</p>\n<ul class=\"fig-list\">\n<li><code>{segments[0].stimulus == stimulus}</code>: Der Stimulus des ersten Segments muss identisch mit dem Gesamtstimulus der Kette sein.</li>\n<li><code>{segments[last].response == response}</code>: Die Response des letzten Segments muss identisch mit der Gesamtresonse der Kette sein.</li>\n<li><code>{segments[N].response == segments[N+1].stimulus}</code>: Die Response eines Segments N muss nahtlos den Stimulus des nachfolgenden Segments N+1 bilden.</li>\n</ul>\n<p class=\"fig-p\">Timing-Analysewerkzeuge müssen bei der Validierung von Latenzzeiten und Ausführungsfristen sicherstellen, dass die zeitliche Kette lückenlos geschlossen und geordnet ist.</p>"}, {"id": "FIG-bb7d19aa9c9c986d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Timing-Modells im Kontext des Virtual Functional Bus (AUTOSAR VFB). Das Diagramm definiert die konzeptionelle Metamodell-Struktur für Timing-Ketten (TimingChains), deren Zusammensetzung aus Teilstrecken sowie die Laufzeit-Repräsentation durch konkrete Aktivierungen und Ereignisvorkommen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert vier Klassen und deren strukturelle Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>Event</code> (abstrakt): Definiert das Ereigniskonzept. Assoziiert mit <code>EventOccurrence</code> über die Assoziationsenden <code>+event</code> (Multiplizität 1) und <code>+occurrences</code> (Multiplizität <code>*</code>).</li>\n<li><code>TimingChain</code>: Repräsentiert eine Timing-Kette. Enthält eine reflexive Komposition <code>+segments</code> mit Multiplizität <code>1..* {ordered}</code> zur hierarchischen/sequenziellen Unterteilung in Kettenglieder. Referenziert genau ein auslösendes Ereignis über die Assoziation <code>+stimulus</code> (Multiplizität 1) sowie genau ein resultierendes Ereignis über <code>+response</code> (Multiplizität 1) zur Klasse <code>Event</code>.</li>\n<li><code>TimingChainActivation</code>: Repräsentiert eine konkrete Ausführung/Aktivierung einer Timing-Kette. Steht in einer 1-zu-n-Beziehung (<code>1</code> zu <code>*</code>) zu <code>TimingChain</code>. Besitzt das Attribut <code>+ responseTime: TimeInterval</code>. Referenziert genau ein auslösendes Ereignisvorkommen über <code>+stimulus</code> (Multiplizität 1) und genau ein Ziel-Ereignisvorkommen über <code>+response</code> (Multiplizität 1) der Klasse <code>EventOccurrence</code>.</li>\n<li><code>EventOccurrence</code>: Repräsentiert das Eintreten eines konkreten Ereignisses mit dem Attribut <code>+ occurrenceTime: TimePoint</code>. Steht als Ausprägungsinstanz in n-zu-1-Beziehung zu <code>Event</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet die statische Korrelation von Entwurfselementen zu deren dynamischen Laufzeitinstanzen ab. Eine <code>TimingChain</code> wird dynamisch durch <code>TimingChainActivation</code> instanziiert, wobei die gemessene Reaktionszeit <code>responseTime</code> der Differenz zwischen dem auslösenden Stimulus-Ereigniszeitpunkt (<code>occurrenceTime</code> des Stimulus-<code>EventOccurrence</code>) und dem Antwort-Ereigniszeitpunkt (<code>occurrenceTime</code> des Response-<code>EventOccurrence</code>) entspricht. Die Segmentierung verlangt eine durchgängige kausale Kette über geordnete Zwischenschritte (<code>segments</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Modellierung und Werkzeugunterstützung gelten folgende OCL- bzw. Konsistenzbedingungen (<code>constraints</code>) auf <code>TimingChain</code>:</p>\n<ul class=\"fig-list\">\n<li><code>{segments[0].stimulus == stimulus}</code>: Der Stimulus des ersten Segments muss identisch mit dem Gesamtstimulus der Kette sein.</li>\n<li><code>{segments[last].response == response}</code>: Die Response des letzten Segments muss identisch mit der Gesamtresonse der Kette sein.</li>\n<li><code>{segments[N].response == segments[N+1].stimulus}</code>: Die Response eines Segments N muss nahtlos den Stimulus des nachfolgenden Segments N+1 bilden.</li>\n</ul>\n<p class=\"fig-p\">Timing-Analysewerkzeuge müssen bei der Validierung von Latenzzeiten und Ausführungsfristen sicherstellen, dass die zeitliche Kette lückenlos geschlossen und geordnet ist.</p>"}], "trans": [{"from": "FIG-d1ad7aab71ab591a", "to": "FIG-bb7d19aa9c9c986d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
